/** A `Cell` (an enum in the circuit): `Cell.Hidden`, or its name, `"Hidden"`. */
export const Cell = {
  Hidden: "Hidden", Clear: "Clear", One: "One", Two: "Two", Three: "Three", Four: "Four", Five: "Five", Six: "Six",
  Seven: "Seven", Eight: "Eight", Mine: "Mine",
} as const;
export type Cell = (typeof Cell)[keyof typeof Cell];

/** A `Board` (an input struct). */
export interface Board {
  /** Exactly 81 elements. */
  mines: readonly boolean[];
  salt: FieldInput;
}

/** Every input of `minesweeper`. */
export interface MinesweeperInputs {
  board: Board;
  commitment: FieldInput;
  /** Exactly 81 elements. */
  view: readonly Cell[];
}

/** The public inputs: what a verifier supplies, and what a proof reveals. */
export interface MinesweeperPublicInputs {
  commitment: FieldInput;
  /** Exactly 81 elements. */
  view: readonly Cell[];
}

/** The public inputs, decoded from a proof. */
export interface MinesweeperPublicValues {
  commitment: Field;
  view: Cell[];
}

/** The input structs, by name: what `fields` takes. */
export interface MinesweeperStructs {
  Board: Board;
}

/**
 * `minesweeper`: make a prover or verifier from a URL serving a copy of
 * `target/xark/minesweeper/` (relative to the page in a browser) or from the bytes:
 *
 * ```ts
 * const prover = await Minesweeper.prover("/circuits/minesweeper/");
 * const proof = prover.prove(inputs);
 * send(proof.toBytes()); // the proof; an exported Solana verifier reads it as is
 * const verifier = await Minesweeper.verifier(vkBytes);
 * verifier.verify(bytes, publicInputs); // true: it proves the public inputs you require
 * ```
 */
export const Minesweeper = new Circuit<MinesweeperInputs, MinesweeperPublicInputs, MinesweeperPublicValues, MinesweeperStructs>({
  name: "minesweeper",
  schema,
  decodePublic,
  client: true,
  digest: "80de68b769d0705ffbdbc053b045d124",
});

export type MinesweeperProver = Prover<MinesweeperInputs, MinesweeperPublicInputs, MinesweeperPublicValues, MinesweeperStructs>;
export type MinesweeperVerifier = Verifier<MinesweeperPublicInputs, MinesweeperPublicValues, MinesweeperStructs>;
export type MinesweeperProof = Proof<MinesweeperPublicValues>;

/** `Board`'s Rust functions (`#[input] impl Board`), run from `client.wasm`. */
export const Board = {
  /**
   * What opening cell `at` (`r * 9 + c`) shows, every other cell hidden: the
   * cell alone if it is a mine, else the flood fill from it (a cell with no
   * neighbouring mines opens its neighbours too).
   */
  reveal(board: Board, at: U8): Cell[] {
    return Minesweeper.call<Json<Cell[]>>("Board.reveal", [board, at]).map((x) => x);
  },
  /**
   * The commitment the house publishes before play: Poseidon2 of the packed
   * board and the salt. 81 bits fit far below the field's modulus, so the
   * packing is injective.
   */
  commitment(board: Board): Field {
    return new Field(Minesweeper.call<Json<Field>>("Board.commitment", [board]));
  },
};

function decodePublic(v: Json<MinesweeperPublicValues>): MinesweeperPublicValues {
  return {
    commitment: new Field(v.commitment),
    view: v.view.map((x) => x),
  };
}
